// A CCamCtrlData tracks a controlled camera's current position and reference
// point each frame; sysCamCtrlStep uses CalcPosRefToDistRot exactly like this
// to recover the distance/angles between them.
local cam_ctrl = CCamCtrlData();
cam_ctrl.now_pos = [10.0, 5.0, -20.0];
cam_ctrl.now_ref = [0.0, 5.0, 0.0];
local dhv = CalcPosRefToDistRot(cam_ctrl.now_pos, cam_ctrl.now_ref);
local distance = dhv[0];
local horizontalAngleDeg = dhv[1];
local verticalAngleDeg = dhv[2];
